package org.jopenagent.trace.viewer;

/** The single self-contained HTML page (inline CSS/JS, no build step, no CDN) served by {@link TraceViewerServer}. */
final class TraceViewerPage {

    private TraceViewerPage() {
    }

    static final String HTML = "<!doctype html>\n" + "<html><head><meta charset=\"utf-8\"><title>jOpenAgent Trace Viewer</title>\n" + "<style>\n"
            + "body { font-family: -apple-system, Segoe UI, sans-serif; margin: 0; display: flex; height: 100vh; background: #0f1115; color: #e6e6e6; }\n"
            + "#list { width: 320px; overflow-y: auto; border-right: 1px solid #2a2d34; padding: 8px; box-sizing: border-box; }\n"
            + "#detail { flex: 1; overflow-y: auto; padding: 16px; box-sizing: border-box; }\n"
            + ".trace-item { padding: 8px; margin-bottom: 4px; border-radius: 6px; cursor: pointer; background: #1a1d24; }\n"
            + ".trace-item:hover { background: #23262f; }\n" + ".trace-item.selected { background: #2d3348; }\n"
            + ".span { border-left: 2px solid #3a3f4b; margin-left: 10px; padding-left: 10px; margin-top: 6px; }\n"
            + ".span-header { font-weight: 600; }\n" + ".span-header.error { color: #ff6b6b; }\n" + ".attr { color: #9aa0ac; font-size: 0.85em; margin-left: 8px; }\n"
            + ".muted { color: #6b7280; font-size: 0.8em; }\n" + "h2 { margin-top: 0; }\n"
            + ".tab-bar { display: flex; margin-bottom: 8px; }\n"
            + ".tab-btn { flex: 1; padding: 6px; background: #1a1d24; border: none; color: #9aa0ac; cursor: pointer; border-radius: 6px; margin-right: 4px; }\n"
            + ".tab-btn:last-child { margin-right: 0; }\n" + ".tab-btn.active { background: #2d3348; color: #e6e6e6; }\n"
            + ".eval-table { border-collapse: collapse; width: 100%; margin-top: 12px; }\n"
            + ".eval-table th, .eval-table td { text-align: left; padding: 6px 10px; border-bottom: 1px solid #2a2d34; font-size: 0.9em; }\n"
            + ".eval-table th { color: #9aa0ac; font-weight: 600; }\n" + ".badge { padding: 2px 8px; border-radius: 10px; font-size: 0.8em; font-weight: 600; }\n"
            + ".badge-pass { background: #16351f; color: #6fd08c; }\n" + ".badge-fail { background: #3a1c1c; color: #ff6b6b; }\n"
            + ".view-trace-link { color: #7aa2f7; cursor: pointer; }\n"
            + ".summary-row { display: flex; gap: 20px; margin-bottom: 8px; }\n" + ".summary-stat { background: #1a1d24; padding: 8px 14px; border-radius: 6px; }\n"
            + ".summary-stat .value { font-size: 1.3em; font-weight: 700; }\n" + "</style></head><body>\n"
            + "<div id=\"list\"><div class=\"tab-bar\">"
            + "<button class=\"tab-btn active\" id=\"tab-traces\" onclick=\"switchTab('traces')\">Traces</button>"
            + "<button class=\"tab-btn\" id=\"tab-experiments\" onclick=\"switchTab('experiments')\">Experiments</button>"
            + "</div><div id=\"items\"></div></div>\n"
            + "<div id=\"detail\"><p class=\"muted\">Select a trace on the left.</p></div>\n" + "<script>\n"
            + "let selected = null;\n" + "let activeTab = 'traces';\n"
            + "function fmt(ms) { return (typeof ms === 'number') ? ms.toFixed(1) + 'ms' : ''; }\n"
            + "function switchTab(tab) {\n" + "  activeTab = tab;\n"
            + "  document.getElementById('tab-traces').classList.toggle('active', tab === 'traces');\n"
            + "  document.getElementById('tab-experiments').classList.toggle('active', tab === 'experiments');\n"
            + "  selected = null;\n" + "  if (tab === 'traces') { refresh(); } else { refreshExperiments(); }\n" + "}\n"
            + "function renderSpan(span) {\n" + "  const div = document.createElement('div');\n" + "  div.className = 'span';\n"
            + "  const header = document.createElement('div');\n" + "  header.className = 'span-header' + (span.status === 'ERROR' ? ' error' : '');\n"
            + "  header.textContent = '[' + span.kind + '] ' + span.name + ' (' + fmt(span.durationMillis) + ')' + (span.status === 'ERROR' ? ' ERROR' : '');\n"
            + "  div.appendChild(header);\n" + "  if (span.error) {\n" + "    const err = document.createElement('div');\n" + "    err.className = 'attr';\n"
            + "    err.textContent = 'error: ' + span.error;\n" + "    div.appendChild(err);\n" + "  }\n"
            + "  if (span.attributes) {\n" + "    for (const key in span.attributes) {\n" + "      const attr = document.createElement('div');\n"
            + "      attr.className = 'attr';\n" + "      let value = span.attributes[key];\n" + "      let text = typeof value === 'string' ? value : JSON.stringify(value);\n"
            + "      if (text && text.length > 200) { text = text.substring(0, 200) + '...'; }\n" + "      attr.textContent = key + ' = ' + text;\n"
            + "      div.appendChild(attr);\n" + "    }\n" + "  }\n" + "  if (span.children) {\n" + "    for (const child of span.children) {\n"
            + "      div.appendChild(renderSpan(child));\n" + "    }\n" + "  }\n" + "  return div;\n" + "}\n"
            + "function loadTrace(id, el) {\n" + "  if (activeTab !== 'traces') { switchTab('traces'); }\n"
            + "  if (selected) selected.classList.remove('selected');\n"
            + "  if (el) { el.classList.add('selected'); selected = el; }\n"
            + "  fetch('/api/trace?id=' + encodeURIComponent(id)).then(r => r.json()).then(span => {\n" + "    const detail = document.getElementById('detail');\n"
            + "    detail.innerHTML = '';\n" + "    const h2 = document.createElement('h2');\n" + "    h2.textContent = span.name;\n" + "    detail.appendChild(h2);\n"
            + "    detail.appendChild(renderSpan(span));\n" + "  });\n" + "}\n"
            + "function refresh() {\n" + "  fetch('/api/traces').then(r => r.json()).then(list => {\n" + "    const container = document.getElementById('items');\n"
            + "    container.innerHTML = '';\n" + "    list.slice().reverse().forEach(t => {\n" + "      const item = document.createElement('div');\n"
            + "      item.className = 'trace-item';\n" + "      item.textContent = t.name + ' (' + fmt(t.durationMillis) + ')' + (t.status === 'ERROR' ? ' \\u26A0' : '');\n"
            + "      item.onclick = function() { loadTrace(t.id, item); };\n" + "      container.appendChild(item);\n" + "    });\n" + "  });\n" + "}\n"
            + "function refreshExperiments() {\n" + "  fetch('/api/eval/experiments').then(r => r.json()).then(list => {\n"
            + "    const container = document.getElementById('items');\n" + "    container.innerHTML = '';\n"
            + "    if (list.length === 0) { container.innerHTML = '<p class=\"muted\">No eval experiments captured yet.</p>'; }\n"
            + "    list.forEach(exp => {\n" + "      const item = document.createElement('div');\n" + "      item.className = 'trace-item';\n"
            + "      item.textContent = exp.id + ' (' + exp.passedCount + '/' + exp.testCount + ' passed)';\n"
            + "      item.onclick = function() { loadExperiment(exp.id, item); };\n" + "      container.appendChild(item);\n" + "    });\n" + "  });\n" + "}\n"
            + "function badgeFor(passed) {\n" + "  const span = document.createElement('span');\n" + "  span.className = 'badge ' + (passed ? 'badge-pass' : 'badge-fail');\n"
            + "  span.textContent = passed ? 'PASS' : 'FAIL';\n" + "  return span;\n" + "}\n"
            + "function loadExperiment(id, el) {\n" + "  if (selected) selected.classList.remove('selected');\n"
            + "  if (el) { el.classList.add('selected'); selected = el; }\n"
            + "  Promise.all([\n" + "    fetch('/api/eval/experiment?id=' + encodeURIComponent(id)).then(r => r.json()),\n"
            + "    fetch('/api/eval/summary?id=' + encodeURIComponent(id)).then(r => r.json())\n" + "  ]).then(([experiment, summary]) => {\n"
            + "    const detail = document.getElementById('detail');\n" + "    detail.innerHTML = '';\n"
            + "    const h2 = document.createElement('h2');\n" + "    h2.textContent = id;\n" + "    detail.appendChild(h2);\n"
            + "    const statsRow = document.createElement('div');\n" + "    statsRow.className = 'summary-row';\n"
            + "    statsRow.innerHTML = '<div class=\"summary-stat\"><div class=\"value\">' + summary.passed + '/' + summary.total\n"
            + "      + '</div>tests passed</div><div class=\"summary-stat\"><div class=\"value\">' + (summary.successRate * 100).toFixed(0)\n"
            + "      + '%</div>success rate</div>';\n" + "    detail.appendChild(statsRow);\n"
            + "    const table = document.createElement('table');\n" + "    table.className = 'eval-table';\n"
            + "    table.innerHTML = '<tr><th>Test</th><th>Tier</th><th>Model</th><th>Score</th><th>Duration</th><th>Result</th><th></th></tr>';\n"
            + "    experiment.results.forEach(t => {\n" + "      const row = document.createElement('tr');\n"
            + "      const link = document.createElement('span');\n" + "      link.className = 'view-trace-link';\n" + "      link.textContent = 'view trace';\n"
            + "      link.onclick = function() { loadTrace(t.spanId, null); };\n"
            + "      const resultCell = document.createElement('td');\n" + "      resultCell.appendChild(badgeFor(t.passed));\n"
            + "      const linkCell = document.createElement('td');\n" + "      linkCell.appendChild(link);\n"
            + "      row.innerHTML = '<td>' + (t.displayName || t.testId) + '</td><td>' + t.tier + '</td><td>' + t.model\n"
            + "        + '</td><td>' + t.score.toFixed(2) + '</td><td>' + fmt(t.durationMillis) + '</td>';\n"
            + "      row.appendChild(resultCell);\n" + "      row.appendChild(linkCell);\n" + "      table.appendChild(row);\n" + "    });\n"
            + "    detail.appendChild(table);\n" + "  });\n" + "}\n"
            + "refresh();\n" + "setInterval(function() { if (activeTab === 'traces') { refresh(); } else { refreshExperiments(); } }, 3000);\n"
            + "</script>\n" + "</body></html>\n";
}
